// meta-ads-poster — creates Meta ad campaigns from ad-creative-studio images
//
// Takes ad creative images (already generated by ad-creative-studio) and:
// 1. Uploads them to Meta's ad image library
// 2. Creates Campaign → Ad Set → Ad Creative → Ad (all PAUSED by default)
// 3. Returns all created IDs + Ads Manager deep-link
//
// Required Supabase secrets (secondary project zmyczlfuufhngzovkjdh):
//   META_USER_ACCESS_TOKEN  — from M2 Api Dev app (Development mode, ads_management)
//   META_AD_ACCOUNT_ID      — "act_1969872620513768" (M2ads)
//
// Called with:
//   POST {"jobId":"...","pageId":"...","niche":"nurse","dailyBudgetCents":500}
//   POST {"jobId":"...","pageId":"...","dryRun":true}  ← validates + returns plan, no API calls
//   POST {"listPages":true}  ← returns all Pages the token has access to
//   POST {"jobId":"...","pageId":"...","brandSlug":"dwa","dailyBudgetCents":500}  ← DWA brand

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const log = (step: string, data?: unknown) =>
  console.log(`[META-POSTER] ${step}${data ? " — " + JSON.stringify(data) : ""}`);

const META = "https://graph.facebook.com/v21.0";

// ── Image upload to Meta ───────────────────────────────────────────────────────
async function uploadImageToMeta(
  imageUrl: string,
  name: string,
  adAccount: string,
  token: string
): Promise<string> {
  // Fetch image bytes from Supabase Storage
  const imgRes = await fetch(imageUrl, { signal: AbortSignal.timeout(30_000) });
  if (!imgRes.ok) throw new Error(`Failed to fetch image: ${imgRes.status} ${imageUrl}`);

  const imgBytes = new Uint8Array(await imgRes.arrayBuffer());
  // Chunked encoding avoids call-stack overflow on large images
  let base64 = "";
  for (let i = 0; i < imgBytes.length; i += 8192) {
    base64 += String.fromCharCode(...imgBytes.subarray(i, i + 8192));
  }
  base64 = btoa(base64);

  log("Uploading image to Meta", { name, bytes: imgBytes.byteLength });

  const uploadRes = await fetch(`${META}/${adAccount}/adimages`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ bytes: base64, name }),
  });

  const uploadData = await uploadRes.json();
  if (uploadData.error) throw new Error(`Meta image upload failed: ${uploadData.error.message}`);

  // Response: { images: { "filename.jpg": { hash, url, ... } } }
  const images = uploadData.images ?? {};
  const firstKey = Object.keys(images)[0];
  if (!firstKey) throw new Error("No image hash returned from Meta");

  const hash = images[firstKey].hash;
  log("Image uploaded", { hash });
  return hash;
}

// ── Create campaign ────────────────────────────────────────────────────────────
async function createCampaign(
  adAccount: string,
  name: string,
  objective: string,
  token: string
): Promise<string> {
  const res = await fetch(`${META}/${adAccount}/campaigns`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      name,
      objective,
      status: "PAUSED",
      special_ad_categories: [],
      is_adset_budget_sharing_enabled: false,
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(`Create campaign failed: ${JSON.stringify(data.error)}`);
  log("Campaign created", { id: data.id, name });
  return data.id;
}

// ── Create ad set ──────────────────────────────────────────────────────────────
async function createAdSet(
  adAccount: string,
  campaignId: string,
  name: string,
  dailyBudgetCents: number,
  objective: string,
  token: string,
  instagramActorId?: string
): Promise<string> {
  // Optimization goal depends on campaign objective
  const goalMap: Record<string, { billing_event: string; optimization_goal: string }> = {
    OUTCOME_AWARENESS: { billing_event: "IMPRESSIONS", optimization_goal: "REACH" },
    OUTCOME_TRAFFIC: { billing_event: "LINK_CLICKS", optimization_goal: "LINK_CLICKS" },
    OUTCOME_ENGAGEMENT: { billing_event: "IMPRESSIONS", optimization_goal: "POST_ENGAGEMENT" },
    OUTCOME_LEADS: { billing_event: "IMPRESSIONS", optimization_goal: "LEAD_GENERATION" },
    OUTCOME_SALES: { billing_event: "IMPRESSIONS", optimization_goal: "OFFSITE_CONVERSIONS" },
  };
  const { billing_event, optimization_goal } = goalMap[objective] ?? goalMap.OUTCOME_AWARENESS;

  const res = await fetch(`${META}/${adAccount}/adsets`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      name,
      campaign_id: campaignId,
      billing_event,
      optimization_goal,
      daily_budget: dailyBudgetCents, // in cents (USD)
      bid_strategy: "LOWEST_COST_WITHOUT_CAP",
      targeting: {
        geo_locations: { countries: ["US"] },
        age_min: 25,
        age_max: 55,
        publisher_platforms: instagramActorId ? ["facebook", "instagram"] : ["facebook"],
        ...(instagramActorId ? {
          facebook_positions: ["feed"],
          instagram_positions: ["stream", "reels"],
        } : {
          facebook_positions: ["feed"],
        }),
        targeting_automation: { advantage_audience: 0 },
      },
      status: "PAUSED",
      // Start immediately (no end date — can be set in Ads Manager)
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(`Create ad set failed: ${JSON.stringify(data.error)}`);
  log("Ad set created", { id: data.id, name });
  return data.id;
}

// ── Create ad creative (image ad) ─────────────────────────────────────────────
async function createAdCreative(
  adAccount: string,
  pageId: string,
  imageHash: string,
  headline: string,
  body: string,
  linkUrl: string,
  ctaType: string,
  name: string,
  token: string,
  instagramActorId?: string
): Promise<string> {
  const res = await fetch(`${META}/${adAccount}/adcreatives`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      name,
      object_story_spec: {
        page_id: pageId,
        ...(instagramActorId ? { instagram_actor_id: instagramActorId } : {}),
        link_data: {
          image_hash: imageHash,
          link: linkUrl,
          message: body,
          name: headline, // headline shown under image
          call_to_action: {
            type: ctaType, // LEARN_MORE | SHOP_NOW | SIGN_UP | GET_QUOTE
            value: { link: linkUrl },
          },
        },
      },
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(`Create creative failed: ${JSON.stringify(data.error)}`);
  log("Creative created", { id: data.id });
  return data.id;
}

// ── Upload video to Meta ───────────────────────────────────────────────────────
async function uploadVideoToMeta(
  videoUrl: string,
  title: string,
  adAccount: string,
  token: string
): Promise<string> {
  // Fetch video bytes from storage
  const vidRes = await fetch(videoUrl, { signal: AbortSignal.timeout(120_000) });
  if (!vidRes.ok) throw new Error(`Failed to fetch video: ${vidRes.status} ${videoUrl}`);

  const vidBytes = new Uint8Array(await vidRes.arrayBuffer());
  log("Video fetched for Meta upload", { bytes: vidBytes.byteLength, title });

  // Multipart upload to Meta
  const form = new FormData();
  form.append("title", title.slice(0, 100));
  form.append("source", new Blob([vidBytes], { type: "video/mp4" }), "ad.mp4");

  const uploadRes = await fetch(`${META}/${adAccount}/advideos`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}` },
    body: form,
  });

  const uploadData = await uploadRes.json();
  if (uploadData.error) throw new Error(`Meta video upload failed: ${uploadData.error.message}`);

  const videoId = uploadData.id;
  if (!videoId) throw new Error("No video ID returned from Meta");
  log("Video uploaded to Meta", { videoId });

  // Wait for Meta to process the video (up to 30s)
  for (let i = 0; i < 6; i++) {
    await new Promise((r) => setTimeout(r, 5_000));
    const statusRes = await fetch(`${META}/${videoId}?fields=status&access_token=${token}`, {
      headers: { "Authorization": `Bearer ${token}` },
    });
    const statusData = await statusRes.json();
    const s = statusData.status?.video_status ?? statusData.status;
    log("Video processing status", { status: s, attempt: i + 1 });
    if (s === "ready" || s === "READY") return videoId;
    if (s === "error" || s === "ERROR") throw new Error(`Meta video processing failed: ${JSON.stringify(statusData)}`);
  }

  log("Video status unknown after 30s — proceeding anyway (Meta may still be processing)");
  return videoId;
}

// ── Create video ad creative ───────────────────────────────────────────────────
async function createVideoAdCreative(
  adAccount: string,
  pageId: string,
  videoId: string,
  headline: string,
  body: string,
  linkUrl: string,
  ctaType: string,
  name: string,
  token: string,
  instagramActorId?: string,
  thumbnailUrl?: string
): Promise<string> {
  const res = await fetch(`${META}/${adAccount}/adcreatives`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      name,
      object_story_spec: {
        page_id: pageId,
        ...(instagramActorId ? { instagram_actor_id: instagramActorId } : {}),
        video_data: {
          video_id: videoId,
          message: body,
          title: headline,
          ...(thumbnailUrl ? { image_url: thumbnailUrl } : {}),
          call_to_action: {
            type: ctaType,
            value: { link: linkUrl },
          },
        },
      },
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(`Create video creative failed: ${JSON.stringify(data.error)}`);
  log("Video creative created", { id: data.id });
  return data.id;
}

// ── Create ad ─────────────────────────────────────────────────────────────────
async function createAd(
  adAccount: string,
  adSetId: string,
  creativeId: string,
  name: string,
  token: string
): Promise<string> {
  const res = await fetch(`${META}/${adAccount}/ads`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      name,
      adset_id: adSetId,
      creative: { creative_id: creativeId },
      status: "PAUSED", // always start PAUSED — activate in Ads Manager after review
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(`Create ad failed: ${JSON.stringify(data.error)}`);
  log("Ad created", { id: data.id });
  return data.id;
}

