// ── Main handler ──────────────────────────────────────────────────────────────
serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: cors });

  const TOKEN = Deno.env.get("META_USER_ACCESS_TOKEN") ?? "";
  const AD_ACCOUNT = Deno.env.get("META_AD_ACCOUNT_ID") ?? "act_1969872620513768";
  const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
  const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

  const json = (data: unknown, status = 200) =>
    new Response(JSON.stringify(data), { status, headers: { ...cors, "Content-Type": "application/json" } });

  const sb = createClient(SUPABASE_URL, SERVICE_KEY, { auth: { persistSession: false } });

  let body: Record<string, unknown> = {};
  try { body = await req.json(); } catch { /* GET or empty body ok */ }

  // ── Mode: listPages — show all FB pages this token can access ───────────────
  if (body.listPages === true) {
    if (!TOKEN) return json({ error: "META_USER_ACCESS_TOKEN not set" }, 400);
    const pagesRes = await fetch(`${META}/me/accounts?fields=id,name,category&limit=25&access_token=${TOKEN}`);
    const pagesData = await pagesRes.json();
    return json({ pages: pagesData.data ?? [], error: pagesData.error?.message ?? null });
  }

  // ── Mode: campaignStats — return status + insights for a brand's campaign ────
  // POST {"campaignStats":"dwa"} — returns spend/impressions/clicks/CTR + campaign status
  if (body.campaignStats) {
    if (!TOKEN) return json({ error: "META_USER_ACCESS_TOKEN not set" }, 400);
    const brandSlug = body.campaignStats as string;
    // Known campaign IDs by brand (created via this function)
    const CAMPAIGN_IDS: Record<string, string> = {
      dwa: "120243880723670377",
    };
    const campaignId = CAMPAIGN_IDS[brandSlug];
    if (!campaignId) return json({ error: `No campaign ID on file for brand: ${brandSlug}` }, 400);

    const [statusRes, insightRes, adSetRes] = await Promise.all([
      fetch(`${META}/${campaignId}?fields=name,status,daily_budget,created_time,objective&access_token=${TOKEN}`),
      fetch(`${META}/${campaignId}/insights?fields=spend,impressions,clicks,ctr,actions&date_preset=last_30d&access_token=${TOKEN}`),
      fetch(`${META}/${campaignId}/adsets?fields=name,status,daily_budget,targeting&access_token=${TOKEN}`),
    ]);
    const [statusData, insightData, adSetData] = await Promise.all([
      statusRes.json(), insightRes.json(), adSetRes.json(),
    ]);

    return json({
      campaignId,
      campaign: statusData,
      insights: insightData?.data?.[0] ?? null,
      adSets: adSetData?.data ?? [],
    });
  }

  // ── Mode: toggleCampaignStatus — activate or pause a campaign ────────────────
  // POST {"toggleCampaignStatus":"dwa","newStatus":"ACTIVE"} or "PAUSED"
  if (body.toggleCampaignStatus) {
    if (!TOKEN) return json({ error: "META_USER_ACCESS_TOKEN not set" }, 400);
    const brandSlug = body.toggleCampaignStatus as string;
    const newStatus = (body.newStatus as string)?.toUpperCase();
    if (!["ACTIVE", "PAUSED"].includes(newStatus)) {
      return json({ error: "newStatus must be ACTIVE or PAUSED" }, 400);
    }
    const CAMPAIGN_IDS: Record<string, string> = {
      dwa: "120243880723670377",
    };
    const campaignId = CAMPAIGN_IDS[brandSlug];
    if (!campaignId) return json({ error: `No campaign ID on file for brand: ${brandSlug}` }, 400);

    const toggleRes = await fetch(`${META}/${campaignId}`, {
      method: "POST",
      headers: { "Authorization": `Bearer ${TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ status: newStatus }),
    });
    const toggleData = await toggleRes.json();
    if (toggleData.error) throw new Error(`Toggle failed: ${JSON.stringify(toggleData.error)}`);
    log("Campaign status toggled", { campaignId, newStatus });
    return json({ success: true, campaignId, newStatus });
  }

  // ── Mode: videoUrl — create a Meta VIDEO ad from a pre-rendered video URL ───
  // POST {"videoUrl":"https://...mp4","brandSlug":"dwa","dailyBudgetCents":500}
  if (body.videoUrl) {
    const videoUrl = body.videoUrl as string;
    const brandSlugV = (body.brandSlug as string) ?? "dwa";
    const budgetV = (body.dailyBudgetCents as number) ?? 500;

    if (!TOKEN) return json({ error: "META_USER_ACCESS_TOKEN not set" }, 400);

    const brand = BRAND_CONFIG[brandSlugV] ?? BRAND_CONFIG.dwa;
    const resolvedPageId = (body.pageId as string) || brand.defaultPageId;
    if (!resolvedPageId) return json({ error: `pageId required for ${brandSlugV}` }, 400);

    const campaignName = `${brand.campaignPrefix} — Video Ad — ${new Date().toISOString().slice(0, 10)}`;
    const headline = brand.campaignPrefix.slice(0, 40);
    const bodyText = brand.bodyTemplate.slice(0, 125);

    log("Starting Meta VIDEO ad post", { videoUrl: videoUrl.slice(0, 80), brandSlugV, budgetV });

    try {
      const videoId = await uploadVideoToMeta(videoUrl, campaignName, AD_ACCOUNT, TOKEN);
      const campaignId = await createCampaign(AD_ACCOUNT, campaignName, brand.objective, TOKEN);
      const adSetId = await createAdSet(
        AD_ACCOUNT, campaignId, `${campaignName} — US 25-55`,
        budgetV, brand.objective, TOKEN, brand.instagramActorId
      );
      const creativeId = await createVideoAdCreative(
        AD_ACCOUNT, resolvedPageId, videoId, headline, bodyText,
        brand.linkUrl, brand.ctaType, `${campaignName} — Creative`, TOKEN, brand.instagramActorId, brand.thumbnailUrl
      );
      const adId = await createAd(AD_ACCOUNT, adSetId, creativeId, campaignName, TOKEN);
      const adsManagerUrl = `https://www.facebook.com/adsmanager/manage/ads?act=${AD_ACCOUNT.replace("act_", "")}&selected_campaign_ids=${campaignId}`;

      const { error: saveErr } = await sb.from("meta_ad_campaigns").upsert({
        job_id: null,
        campaign_id: campaignId,
        adset_id: adSetId,
        creative_id: creativeId,
        ad_id: adId,
        page_id: resolvedPageId,
        brand_slug: brandSlugV,
        campaign_name: campaignName,
        status: "PAUSED",
        daily_budget_cents: budgetV,
        ads_manager_url: adsManagerUrl,
        image_url: videoUrl,
        created_at: new Date().toISOString(),
      }, { onConflict: "campaign_id", ignoreDuplicates: false });
      if (saveErr) log("DB save warning (non-fatal)", { err: saveErr.message });

      return json({
        success: true, campaignId, adSetId, creativeId, adId, videoId,
        status: "PAUSED",
        adsManagerUrl,
        note: "Video campaign is PAUSED — go to Ads Manager to review + activate",
        placements: brand.instagramActorId ? "Facebook Feed + Instagram Feed + Reels" : "Facebook Feed",
        dailyBudgetUsd: budgetV / 100,
      });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      log("Video ad error", { error: msg });
      return json({ error: msg }, 500);
    }
  }

  // ── Validate required params ───────────────────────────────────────────────
  const { jobId, pageId, brandSlug = "m2", dailyBudgetCents = 500, dryRun = false, linkUrl: linkUrlOverride } = body as {
    jobId?: string;
    pageId?: string;
    brandSlug?: string;
    dailyBudgetCents?: number;
    dryRun?: boolean;
    linkUrl?: string; // optional override for landing URL (adds UTM per-campaign)
  };

  if (!jobId) return json({ error: "jobId required — get from ad_studio_jobs table" }, 400);
  if (!TOKEN) return json({ error: "META_USER_ACCESS_TOKEN not set in Supabase secrets" }, 400);

  const brand = BRAND_CONFIG[brandSlug as string] ?? BRAND_CONFIG.m2;
  // Allow per-call linkUrl override so callers can pass campaign-specific UTM URLs
  if (linkUrlOverride) brand.linkUrl = linkUrlOverride;
  const resolvedPageId = (pageId as string) || brand.defaultPageId;
  if (!resolvedPageId) return json({ error: `pageId required for ${brandSlug} — no default set yet. Call {listPages:true} to find yours.` }, 400);

  try {
    // ── Fetch the ad creative job ─────────────────────────────────────────────
    const { data: job, error: jobErr } = await sb
      .from("ad_studio_jobs")
      .select("*")
      .eq("id", jobId)
      .single();

    if (jobErr || !job) return json({ error: `Job not found: ${jobErr?.message}` }, 404);

    const j = job as {
      id: string;
      product: string;
      concept_name: string;
      niche: string;
      format_urls: Record<string, string>; // {meta_feed: url, meta_story: url, meta_link: url}
      headline?: string;
      subhead?: string;
    };

    // Pick the best image: meta_link (1.91:1) for feed ads, meta_feed (1:1) as fallback
    const imageUrl = j.format_urls?.meta_link ?? j.format_urls?.meta_feed ?? Object.values(j.format_urls ?? {})[0];
    if (!imageUrl) return json({ error: "No image URL in job — run ad-creative-studio first" }, 400);

    const campaignName = `${brand.campaignPrefix} — ${j.concept_name ?? j.niche} — ${new Date().toISOString().slice(0, 10)}`;
    const headline = (j.headline ?? `${j.concept_name} — ${j.niche}`).slice(0, 40);
    const bodyText = (j.subhead ?? brand.bodyTemplate).slice(0, 125);

    log("Starting Meta ad post", {
      jobId,
      campaign: campaignName,
      imageUrl: imageUrl.slice(0, 80),
      pageId: resolvedPageId,
      brandSlug,
      dailyBudgetCents,
      dryRun,
    });

    if (dryRun) {
      return json({
        dryRun: true,
        plan: {
          campaign: campaignName,
          objective: brand.objective,
          pageId: resolvedPageId,
          adAccount: AD_ACCOUNT,
          imageUrl,
          headline,
          bodyText: bodyText.slice(0, 60) + "...",
          ctaType: brand.ctaType,
          linkUrl: brand.linkUrl,
          dailyBudgetUsd: dailyBudgetCents / 100,
          placements: brand.instagramActorId ? "Facebook Feed + Instagram Feed + Reels" : "Facebook Feed only",
          instagramActorId: brand.instagramActorId ?? null,
          status: "PAUSED (activate in Ads Manager after review)",
        },
        nextStep: "Remove dryRun:true to create the campaign",
      });
    }

    // ── Step 1: Upload image ──────────────────────────────────────────────────
    const imageHash = await uploadImageToMeta(
      imageUrl,
      `${j.slug ?? j.niche}_${j.concept ?? "ad"}_${Date.now()}.jpg`,
      AD_ACCOUNT,
      TOKEN
    );

    // ── Step 2: Create Campaign ───────────────────────────────────────────────
    const campaignId = await createCampaign(AD_ACCOUNT, campaignName, brand.objective, TOKEN);

    // ── Step 3: Create Ad Set ─────────────────────────────────────────────────
    const adSetId = await createAdSet(
      AD_ACCOUNT,
      campaignId,
      `${campaignName} — US 25-55`,
      dailyBudgetCents,
      brand.objective,
      TOKEN,
      brand.instagramActorId
    );

    // ── Step 4: Create Creative ───────────────────────────────────────────────
    const creativeId = await createAdCreative(
      AD_ACCOUNT,
      resolvedPageId,
      imageHash,
      headline,
      bodyText,
      brand.linkUrl,
      brand.ctaType,
      `${campaignName} — Creative`,
      TOKEN,
      brand.instagramActorId
    );

    // ── Step 5: Create Ad (PAUSED) ────────────────────────────────────────────
    const adId = await createAd(AD_ACCOUNT, adSetId, creativeId, campaignName, TOKEN);

    const adsManagerUrl = `https://www.facebook.com/adsmanager/manage/ads?act=${AD_ACCOUNT.replace("act_", "")}&selected_campaign_ids=${campaignId}`;

    log("Done", { campaignId, adSetId, creativeId, adId });

    // ── Save to DB ────────────────────────────────────────────────────────────
    const { error: saveErr } = await sb.from("meta_ad_campaigns").upsert({
      job_id: jobId,
      campaign_id: campaignId,
      adset_id: adSetId,
      creative_id: creativeId,
      ad_id: adId,
      page_id: resolvedPageId,
      brand_slug: brandSlug,
      campaign_name: campaignName,
      status: "PAUSED",
      daily_budget_cents: dailyBudgetCents,
      ads_manager_url: adsManagerUrl,
      image_url: imageUrl,
      created_at: new Date().toISOString(),
    }, { onConflict: "campaign_id", ignoreDuplicates: false });

    if (saveErr) log("DB save warning (non-fatal)", { err: saveErr.message });

    return json({
      success: true,
      campaignId,
      adSetId,
      creativeId,
      adId,
      status: "PAUSED",
      adsManagerUrl,
      note: "Campaign is PAUSED — go to Ads Manager to review + activate",
      imageUploaded: imageUrl,
      dailyBudgetUsd: dailyBudgetCents / 100,
    });

  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log("Error", { error: msg });
    return json({ error: msg }, 500);
  }
});
